/// <summary>
/// Contract class for Update slot area
/// </summary>
[DataContractAttribute, SysOperationContractProcessing(ClassStr(METUpdateSlotAreaUIBuilder))]
class METUpdateSlotAreaContract extends METSysOperationTaskDataContract
{
    guid topPickingProcessId;
    InventLocationId inventLocationId;
    METNoOfRecords metNoOfRecords;


}

Method.Source:
/// <summary>
/// get/set the top picking process guid id
/// </summary>
/// <param name = "_topPickingProcessId">guid</param>
/// <returns>guid</returns>
[DataMember, SysOperationControlVisibilityAttribute(false)]
public guid parmTopPickingProcessId(guid _topPickingProcessId = topPickingProcessId)
{
    topPickingProcessId = _topPickingProcessId;

    return topPickingProcessId;
}

/// <summary>
/// Warehouse 
/// </summary>
/// <param name = "_inventLocationId">InventLocationId</param>
/// <returns>InventLocationId</returns>
[DataMember]
public InventLocationId parmInventLocationId(InventLocationId _inventLocationId = inventLocationId)
{
    inventLocationId = _inventLocationId;

    return inventLocationId;
}

/// <summary>
/// Number of thread
/// </summary>
/// <param name = "_threadCount">METThreadCount</param>
/// <returns>Thread count</returns>
[DataMember]
public METThreadCount parmThreadCount(METThreadCount _threadCount = threadCount)
{
    threadCount = _threadCount;

    return threadCount;
}

/// <summary>
/// Number of records
/// </summary>
/// <param name = "_threadCount">METNoOfRecords</param>
/// <returns>Number of records</returns>
[DataMember]
public METNoOfRecords parmMETNoOfRecords(METNoOfRecords _metNoOfRecords = metNoOfRecords)
{
    metNoOfRecords = _metNoOfRecords;

    return metNoOfRecords;
}
